before.rawRule:
.bg-status-info\/80 {
    background-color: var(--status-info);
    @supports (color: color-mix(in lab, red, red)) {
      background-color: color-mix(in oklab, var(--status-info) 80%, transparent);
    }
  }

after.rawRule:
  .closedOverlaySold {
    background-color: var(--status-info); /* retired status-info bg utility's static fallback */
    border-color:      var(--status-info); /* retired status-info border utility */
  }

  .closedOverlayRented {
    background-color: var(--status-rented); /* retired status-rented bg utility's static fallback */
    border-color:      var(--status-rented); /* retired status-rented border utility */
  }
}
@supports (color: color-mix(in lab, red, red)) {
  @layer utilities {
    .closedOverlaySold {
      background-color: color-mix(in oklab, var(--status-info) 80%, transparent); /* retired status-info bg utility, color-mix tier */
    }
    .closedOverlayRented {
      background-color: color-mix(in oklab, var(--status-rented) 80%, transparent); /* retired status-rented bg utility, color-mix tier */
    }
  }
}

.closedOverlaySold {
  background-color: var(--status-info); /* retired status-info bg utility's static fallback */
  border-color:      var(--status-info); /* retired status-info border utility */
}

before.rawRule:
